WITH up AS (INSERT INTO public.packages (slug, name, type, description, long_description, author_handle, is_published, latest_version, scopes, source_kind, source_ref, review_status) VALUES ('gtm-account-tiering-strategist', 'GTM Account Tiering Strategist', 'skill', 'Builds T1/T2/T3 ABM tiers with firmographic fit, intent signals, and SLA-backed coverage rules.', 'Use when defining or auditing ABM tiers across sales, marketing, and partnerships. Returns a scoring matrix, coverage planner, and governance checklist anchored on revenue priorities.', '@superagentskill', true, '0.1.0', ARRAY['agent:upgrade','registry:read'], 'github', 'content/skills/gtm-account-tiering-strategist.yaml', 'approved') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, long_description=EXCLUDED.long_description, is_published=true, review_status='approved', updated_at=now() RETURNING id) INSERT INTO public.package_versions (package_id, version, status, notes, system_prompt, rules, examples, compatibility) SELECT id, '0.1.0', 'stable', 'Seeded from gtm-agents batch', 'You are an ABM strategist. For each request, return: (1) tier definitions with firmographic + intent + strategic-value scoring, (2) a coverage planner mapping tier to owner type to touch cadence, (3) SLA expectations per tier (touches/quarter, personalization depth), (4) a quarterly governance checklist. Cite the data source for every signal.', '{"must":["Follow the section order specified in the system prompt."],"must_not":["Invent facts, customers, or competitor claims not grounded in the input."]}'::jsonb, '[{"title":"Typical request","input":"<fill with a realistic GTM scenario>","expected_output":"<structured response per system prompt>"}]'::jsonb, '[{"runtime":"claude","status":"supported"},{"runtime":"gpt","status":"supported"},{"runtime":"gemini","status":"supported"}]'::jsonb FROM up ON CONFLICT (package_id, version) DO UPDATE SET system_prompt=EXCLUDED.system_prompt, rules=EXCLUDED.rules, examples=EXCLUDED.examples, compatibility=EXCLUDED.compatibility;

